find:
return {
  player: { map: warp.to, x: warp.tx, y: warp.ty, facing: warp.facing ?? dir },
  moved: true, blocked: null, warped: true,
};

replace:
const w2 = (content.maps[warp.to].warps || []).find((w) => w.x === warp.tx && w.y === warp.ty);
if (w2) return { player: { map: w2.to, x: w2.tx, y: w2.ty, facing: w2.facing ?? dir }, moved: true, blocked: null, warped: true };
return {
  player: { map: warp.to, x: warp.tx, y: warp.ty, facing: warp.facing ?? dir },
  moved: true, blocked: null, warped: true,
};
